   463→fn parse_stmt(p: *Parser) -> ASTNode {
   464→    if match_token(p, TOK_VAR) == 1 {
   465→        advance(p);
   466→        var n: ASTNode = new_ast_node(AST_VAR);
   467→
   468→        if match_token(p, TOK_IDENT) == 1 {
   469→            var cur: *Token = token_at(p);
   470→            n.name = cur.name;
   471→            advance(p);
   472→        }
   473→
   474→        consume(p, TOK_COLON);
   475→
   476→        if match_token(p, TOK_IDENT) == 1 {
   477→            var type_tok: *Token = token_at(p);
   478→            n.type_name = type_tok.name;
   479→            advance(p);
   480→        }
   481→
   482→        if consume(p, TOK_ASSIGN) == 1 {
   483→            n.right = 0;  // placeholder
   484→        }
   485→
   486→        consume(p, TOK_SEMICOLON);
   487→        return n;
   488→    }
   489→
   490→    if match_token(p, TOK_RETURN) == 1 {
   491→        advance(p);
   492→        var n: ASTNode = new_ast_node(AST_RETURN);
   493→
   494→        if match_token(p, TOK_SEMICOLON) == 0 {
   495→            n.right = 0;  // placeholder for expression
   496→        }
   497→
   498→        consume(p, TOK_SEMICOLON);
   499→        return n;
   500→    }
   501→
   502→    var n: ASTNode = new_ast_node(AST_EXPR_STMT);
   503→    n.right = 0;  // placeholder
   504→    consume(p, TOK_SEMICOLON);
   505→    return n;
   506→}
