   540→    }
   541→
   542→    if match_token(p, TOK_IDENT) == 1 {
   543→        var cur: *Token = token_at(p);
   544→        var n: ASTNode = new_ast_node(AST_IDENT);
   545→        n.name = cur.name;
   546→        advance(p);
