   577→fn binop_str(op: i64) -> string {
   578→    if op == TOK_PLUS { return "+"; }
   579→    if op == TOK_MINUS { return "-"; }
   580→    if op == TOK_STAR { return "*"; }
   581→    if op == TOK_SLASH { return "/"; }
   582→    if op == TOK_EQ { return "=="; }
   583→    if op == TOK_NE { return "!="; }
   584→    if op == TOK_LT { return "<"; }
   585→    if op == TOK_GT { return ">"; }
   586→    if op == TOK_LE { return "<="; }
   587→    if op == TOK_GE { return ">="; }
   588→    if op == TOK_AND { return "&&"; }
