   255→fn become_leader(node: RaftNode) -> RaftNode {
   256→    node.state = RaftState.Leader;
   257→    node.votes_received = 0;
   258→
   259→    // Initialize next_index and match_index
   260→    let i = 0;
   261→    while (i < node.num_nodes) {
   262→        node.next_index[i] = node.log.len();
   263→        node.match_index[i] = 0;
   264→        i = i + 1;
   265→    };
   266→
   267→    // Set self as already replicated
   268→    node.match_index[node.id] = node.log.len() - 1;
