   275→// ----- Key Method 4: replicate_log -----
   276→// Leader sends log entries to followers
   277→
   278→fn replicate_log(node: RaftNode, entry: LogEntry) -> RaftNode {
   279→    if (node.state != RaftState.Leader) {
   280→        return node;
   281→    };
   282→
   283→    // Add entry to leader's log
   284→    node.log.push(entry);
   285→    node.match_index[node.id] = node.log.len() - 1;
