   436→
   437→fn get_last_log_index(node: RaftNode) -> u64 {
   438→    if (node.log.len() == 0) {
   439→        return 0;
   440→    };
   441→
   442→    node.log[node.log.len() - 1].index
   443→}
   444→
   445→fn get_last_log_term(node: RaftNode) -> u64 {
   446→    if (node.log.len() == 0) {
   447→        return 0;
   448→    };
   449→
   450→    node.log[node.log.len() - 1].term
   451→}
