    37→}
    38→
    39→// ----- Hash Function -----
    40→
    41→fn hash_key(key: string) -> u64 {
    42→    // Simple hash: sum of character codes
    43→    let hash: u64 = 5381;
    44→    let i = 0;
    45→    while (i < key.len()) {
    46→        let c = key[i] as u64;
    47→        hash = ((hash << 5) + hash) + c;
    48→        i = i + 1;
    49→    };
    50→
    51→    hash
    52→}
    53→
    54→fn hash_node(node_id: u32, virtual_idx: u32) -> u64 {
    55→    let combined = node_id * 1000 + virtual_idx;
    56→    hash_key("node:" + combined)
    57→}
    58→
    59→// ----- ConsistentHashRing -----
    60→
    61→fn new_consistent_hash_ring(virtual_nodes: u32) -> ConsistentHashRing {
    62→    ConsistentHashRing {
    63→        virtual_nodes: virtual_nodes,
    64→        nodes: [],
    65→        node_list: [],
    66→        hash_map: {},
    67→    }
    68→}
    69→
    70→fn add_node_to_ring(ring: ConsistentHashRing, node_id: u32) -> ConsistentHashRing {
    71→    // Add virtual nodes
    72→    let i = 0;
    73→    while (i < ring.virtual_nodes) {
    74→        let hash = hash_node(node_id, i);
    75→
    76→        let hash_node_struct = HashNode {
    77→            hash: hash,
    78→            node_id: node_id,
    79→            is_virtual: true,
    80→        };
    81→
    82→        ring.nodes.push(hash_node_struct);
    83→        ring.hash_map[hash] = node_id;
    84→
    85→        i = i + 1;
    86→    };
    87→
    88→    // Add to node list (if not already there)
    89→    let found = false;
    90→    let j = 0;
    91→    while (j < ring.node_list.len()) {
    92→        if (ring.node_list[j] == node_id) {
    93→            found = true;
    94→            break;
    95→        };
    96→        j = j + 1;
    97→    };
    98→
    99→    if (!found) {
   100→        ring.node_list.push(node_id);
   101→    };
   102→
   103→    // Sort nodes by hash
   104→    sort_hash_nodes(ring.nodes);
   105→
   106→    ring
   107→}
   108→
   109→fn remove_node_from_ring(ring: ConsistentHashRing, node_id: u32) -> ConsistentHashRing {
   110→    // Remove all virtual nodes of this node
   111→    let new_nodes = [];
   112→    let i = 0;
   113→    while (i < ring.nodes.len()) {
   114→        if (ring.nodes[i].node_id != node_id) {
   115→            new_nodes.push(ring.nodes[i]);
   116→        };
   117→        i = i + 1;
   118→    };
   119→
   120→    ring.nodes = new_nodes;
   121→
   122→    // Remove from node list
   123→    let new_node_list = [];
   124→    let j = 0;
   125→    while (j < ring.node_list.len()) {
   126→        if (ring.node_list[j] != node_id) {
   127→            new_node_list.push(ring.node_list[j]);
   128→        };
   129→        j = j + 1;
   130→    };
   131→
   132→    ring.node_list = new_node_list;
   133→
   134→    // Rebuild hash map
   135→    let new_hash_map = {};
   136→    let k = 0;
   137→    while (k < ring.nodes.len()) {
   138→        new_hash_map[ring.nodes[k].hash] = ring.nodes[k].node_id;
   139→        k = k + 1;
   140→    };
   141→
   142→    ring.hash_map = new_hash_map;
   143→
   144→    ring
   145→}
   146→
   147→// Simple bubble sort for hash nodes
   148→fn sort_hash_nodes(nodes: array) {
   149→    let i = 0;
   150→    while (i < nodes.len()) {
   151→        let j = i + 1;
   152→        while (j < nodes.len()) {
   153→            if (nodes[j].hash < nodes[i].hash) {
   154→                let temp = nodes[i];
   155→                nodes[i] = nodes[j];
   156→                nodes[j] = temp;
   157→            };
   158→            j = j + 1;
   159→        };
   160→        i = i + 1;
   161→    };
   162→}
   163→
   164→// ----- Ring Lookup -----
   165→
   166→fn get_node_for_key(ring: ConsistentHashRing, key: string) -> u32 {
   167→    if (ring.node_list.len() == 0) {
   168→        return 0;
   169→    };
   170→
   171→    let key_hash = hash_key(key);
   172→
   173→    // Find first node >= key_hash
   174→    let i = 0;
   175→    while (i < ring.nodes.len()) {
   176→        if (ring.nodes[i].hash >= key_hash) {
   177→            return ring.nodes[i].node_id;
   178→        };
   179→        i = i + 1;
   180→    };
   181→
   182→    // Wrap around to first node
   183→    ring.nodes[0].node_id
   184→}
   185→
   186→fn get_replica_nodes(ring: ConsistentHashRing, key: string, factor: u32) -> array {
   187→    let replicas = [];
   188→    let key_hash = hash_key(key);
   189→    let seen = {};
   190→
   191→    let i = 0;
   192→    let count = 0;
   193→    while (i < ring.nodes.len() && count < factor) {
   194→        let node_id = ring.nodes[i].node_id;
   195→
   196→        // Add if not seen before
   197→        if (!seen[node_id]) {
   198→            replicas.push(node_id);
   199→            seen[node_id] = true;
   200→            count = count + 1;
   201→        };
   202→
   203→        i = i + 1;
   204→    };
   205→
   206→    // Wrap around
   207→    let j = 0;
   208→    while (j < ring.nodes.len() && count < factor) {
   209→        let node_id = ring.nodes[j].node_id;
   210→
   211→        if (!seen[node_id]) {
   212→            replicas.push(node_id);
   213→            seen[node_id] = true;
   214→            count = count + 1;
   215→        };
   216→
   217→        j = j + 1;
   218→    };
   219→
   220→    replicas
   221→}
