   307→        node_counts[primary] = node_counts[primary] + 1;
   308→    };
   309→
   310→    // Convert to array
   311→    for node_id in store.ring.node_list {
   312→        let count = node_counts[node_id] || 0;
   313→
   314→        let stat = BalanceStats {
   315→            node_id: node_id,
   316→            key_count: count,
   317→            total_size: count * 100,  // Assume 100 bytes per key
   318→        };
   319→
   320→        stats.push(stat);
   321→    };
   322→
