   326→fn check_balance(store: ShardedKVStore) -> bool {
   327→    let stats = get_balance_stats(store);
   328→
   329→    if (stats.len() < 2) {
   330→        return true;
   331→    };
   332→
   333→    // Check if keys are roughly balanced
   334→    let total_keys = 0;
   335→    let i = 0;
   336→    while (i < stats.len()) {
   337→        total_keys = total_keys + stats[i].key_count;
   338→        i = i + 1;
   339→    };
   340→
   341→    let avg_keys = total_keys / stats.len();
   342→    let threshold = avg_keys / 2;  // Allow ±50%
   343→
   344→    // Check each node
   345→    let balanced = true;
   346→    let j = 0;
   347→    while (j < stats.len()) {
   348→        let deviation = abs(stats[j].key_count as i64 - avg_keys as i64);
   349→        if (deviation > threshold as i64) {
   350→            balanced = false;
   351→            break;
   352→        };
   353→        j = j + 1;
   354→    };
   355→
   356→    balanced
   357→}
