     2→// Part 3: State Machine and Database Operations
     3→// Purpose: Implement a distributed key-value database using Raft consensus
     4→
     5→// ============ Type Definitions ============
     6→
     7→// Command types for the state machine
     8→enum CommandType {
     9→    Get,
    10→    Set,
    11→    Delete,
    12→    Exists
    13→}
    14→
    15→// DBCommand represents a command to apply to the state machine
    16→struct DBCommand {
    17→    commandType: CommandType,
    18→    key: string,
    19→    value: string,
    20→    timestamp: i32
    21→}
    22→
    23→// DBResponse represents the response from a database operation
    24→struct DBResponse {
    25→    success: bool,
    26→    value: string,
    27→    error: string,
    28→    term: i32
    29→}
    30→
    31→// StateMachine represents the key-value store state machine
    32→struct StateMachine {
    33→    data: array,
    34→    lastAppliedIndex: i32,
    35→    lastAppliedTerm: i32
    36→}
    37→
    38→// DistributedDB combines Raft consensus with state machine
    39→struct DistributedDB {
    40→    consensus: RaftConsensus,
    41→    stateMachine: StateMachine,
    42→    uncommittedCommands: array,
    43→    responses: array
    44→}
    45→
    46→// ============ State Machine Initialization ============
    47→
    48→fn create_state_machine() -> StateMachine {
    49→    let sm = StateMachine {
    50→        data: [],
    51→        lastAppliedIndex: 0,
    52→        lastAppliedTerm: 0
    53→    };
    54→    return sm;
    55→}
    56→
    57→// ============ Database Operations ============
    58→
    59→fn db_set(db: DistributedDB, key: string, value: string, timestamp: i32) -> DistributedDB {
    60→    // Only leader can accept writes
    61→    if db.consensus.node.state != NodeState.Leader {
    62→        let response = DBResponse {
    63→            success: false,
    64→            value: "",
    65→            error: "Not leader",
    66→            term: db.consensus.node.currentTerm
    67→        };
    68→        push(db.responses, response);
    69→        return db;
    70→    }
    71→
    72→    // Create command
    73→    let command = DBCommand {
    74→        commandType: CommandType.Set,
    75→        key: key,
    76→        value: value,
    77→        timestamp: timestamp
    78→    };
    79→
    80→    // Append to log
    81→    let commandStr = "SET:" + key + ":" + value;
    82→    db.consensus.node = append_log_entry(db.consensus.node, commandStr);
    83→
    84→    // Store uncommitted command for tracking
    85→    push(db.uncommittedCommands, command);
    86→
    87→    let response = DBResponse {
    88→        success: true,
    89→        value: "",
    90→        error: "",
    91→        term: db.consensus.node.currentTerm
    92→    };
    93→    push(db.responses, response);
    94→    return db;
    95→}
    96→
    97→fn db_get(db: DistributedDB, key: string) -> DistributedDB {
    98→    // Get can be served by any node with current term (read from state machine)
    99→    let value = "";
   100→    let found = false;
   101→
   102→    let i = 0;
   103→    while i < length(db.stateMachine.data) {
   104→        let entry = db.stateMachine.data[i];
   105→        if entry.key == key {
   106→            value = entry.value;
   107→            found = true;
   108→        }
   109→        i = i + 1;
   110→    }
   111→
   112→    let response = DBResponse {
   113→        success: found,
   114→        value: value,
   115→        error: if found then "" else "Key not found",
   116→        term: db.consensus.node.currentTerm
   117→    };
   118→    push(db.responses, response);
   119→    return db;
   120→}
   121→
   122→fn db_delete(db: DistributedDB, key: string, timestamp: i32) -> DistributedDB {
   123→    // Only leader can accept deletes
   124→    if db.consensus.node.state != NodeState.Leader {
   125→        let response = DBResponse {
   126→            success: false,
   127→            value: "",
   128→            error: "Not leader",
   129→            term: db.consensus.node.currentTerm
   130→        };
   131→        push(db.responses, response);
   132→        return db;
   133→    }
   134→
   135→    // Create command
   136→    let command = DBCommand {
   137→        commandType: CommandType.Delete,
   138→        key: key,
   139→        value: "",
   140→        timestamp: timestamp
   141→    };
   142→
   143→    // Append to log
   144→    let commandStr = "DEL:" + key;
   145→    db.consensus.node = append_log_entry(db.consensus.node, commandStr);
   146→
   147→    // Store uncommitted command
   148→    push(db.uncommittedCommands, command);
   149→
   150→    let response = DBResponse {
   151→        success: true,
   152→        value: "",
   153→        error: "",
   154→        term: db.consensus.node.currentTerm
   155→    };
   156→    push(db.responses, response);
   157→    return db;
   158→}
   159→
   160→// ============ State Machine Application ============
   161→
   162→fn apply_committed_entries(db: DistributedDB) -> DistributedDB {
   163→    let lastIndex = db.stateMachine.lastAppliedIndex;
   164→
   165→    // Apply all committed entries
   166→    while lastIndex < db.consensus.node.commitIndex {
   167→        lastIndex = lastIndex + 1;
   168→
   169→        if lastIndex > 0 && lastIndex <= get_log_length(db.consensus.node) {
   170→            let entry = db.consensus.node.logs[lastIndex - 1];
   171→
   172→            // Parse and apply command
   173→            if starts_with(entry.command, "SET:") {
   174→                let parts = split_string(entry.command, ":");
   175→                if length(parts) >= 3 {
   176→                    let key = parts[1];
   177→                    let value = parts[2];
   178→
   179→                    // Add or update in state machine
   180→                    let found = false;
   181→                    let i = 0;
   182→                    while i < length(db.stateMachine.data) {
   183→                        if db.stateMachine.data[i].key == key {
   184→                            db.stateMachine.data[i].value = value;
   185→                            found = true;
   186→                        }
   187→                        i = i + 1;
   188→                    }
   189→
   190→                    if !found {
   191→                        let newEntry = DBCommand {
   192→                            commandType: CommandType.Set,
   193→                            key: key,
   194→                            value: value,
   195→                            timestamp: 0
   196→                        };
   197→                        push(db.stateMachine.data, newEntry);
   198→                    }
   199→                }
   200→            } else if starts_with(entry.command, "DEL:") {
   201→                let parts = split_string(entry.command, ":");
   202→                if length(parts) >= 2 {
   203→                    let key = parts[1];
   204→
   205→                    // Remove from state machine
   206→                    let i = 0;
   207→                    while i < length(db.stateMachine.data) {
   208→                        if db.stateMachine.data[i].key == key {
   209→                            // Remove by shifting
   210→                            let j = i;
   211→                            while j < length(db.stateMachine.data) - 1 {
   212→                                db.stateMachine.data[j] = db.stateMachine.data[j + 1];
   213→                                j = j + 1;
   214→                            }
   215→                            // Pop last element
   216→                            if length(db.stateMachine.data) > 0 {
   217→                                db.stateMachine.data = take(db.stateMachine.data, length(db.stateMachine.data) - 1);
   218→                            }
   219→                        }
   220→                        i = i + 1;
   221→                    }
   222→                }
   223→            }
   224→
   225→            db.stateMachine.lastAppliedIndex = lastIndex;
   226→            db.stateMachine.lastAppliedTerm = entry.term;
   227→        }
   228→    }
   229→
   230→    return db;
   231→}
