   245→// ============ Utility Functions ============
   246→
   247→fn starts_with(str: string, prefix: string) -> bool {
   248→    // Simple string prefix check
   249→    if length(str) < length(prefix) {
   250→        return false;
   251→    }
   252→    let i = 0;
   253→    while i < length(prefix) {
   254→        if str[i] != prefix[i] {
   255→            return false;
   256→        }
   257→        i = i + 1;
   258→    }
   259→    return true;
   260→}
   261→
   262→fn split_string(str: string, delimiter: string) -> array {
   263→    // Simple string split
   264→    let parts = [];
   265→    let current = "";
   266→    let i = 0;
   267→    while i < length(str) {
   268→        if str[i] == delimiter[0] {
   269→            push(parts, current);
   270→            current = "";
   271→        } else {
   272→            current = current + str[i];
   273→        }
   274→        i = i + 1;
   275→    }
   276→    if length(current) > 0 {
   277→        push(parts, current);
   278→    }
   279→    return parts;
   280→}
   281→
   282→fn take(arr: array, n: i32) -> array {
   283→    let result = [];
   284→    let i = 0;
   285→    while i < n && i < length(arr) {
   286→        push(result, arr[i]);
   287→        i = i + 1;
   288→    }
   289→    return result;
   290→}
