     3→/* Result enum-like structure */
     4→struct Result {
     5→    is_ok: i64,      /* 1 = ok, 0 = error */
     6→    value: i64,      /* success value */
     7→    error: i64,      /* error code */
     8→}
     9→
    10→fn safe_divide(a: i64, b: i64) -> Result {
    11→    var result: Result;
    12→    if (b == 0) {
    13→        result.is_ok = 0;
    14→        result.error = 1;  /* DivideByZero */
    15→    } else {
    16→        result.is_ok = 1;
    17→        result.value = a / b;
    18→        result.error = 0;
    19→    }
    20→    return result;
    21→}
    22→
    23→fn main() -> i64 {
    24→    var res: Result = safe_divide(10, 2);
    25→    if (res.is_ok == 1) {
    26→        return res.value;  /* 5 */
    27→    }
    28→    return res.error;
    29→}
