    18→let js_code = "// fv_lang_wasm.js - FreeLang mini-wasm-pack 생성
let wasm_instance = null;
let wasm_memory = null;
export async function init(wasm_path) {
  const response = await fetch(wasm_path || './fv_lang_wasm_bg.wasm');
  const bytes = await response.arrayBuffer();
  const imports = { env: { memory: new WebAssembly.Memory({ initial: 16 }) } };
  const result = await WebAssembly.instantiate(bytes, imports);
  wasm_instance = result.instance;
  wasm_memory = wasm_instance.exports.memory || imports.env.memory;
  return wasm_instance;
}
function write_string(str) {
  const encoder = new TextEncoder();
  const bytes = encoder.encode(str);
  const ptr = wasm_instance.exports.alloc(bytes.length + 1);
  const mem = new Uint8Array(wasm_memory.buffer);
  mem.set(bytes, ptr);
  mem[ptr + bytes.length] = 0;
  return [ptr, bytes.length];
}
function read_string(ptr, len) {
  const mem = new Uint8Array(wasm_memory.buffer);
  return new TextDecoder().decode(mem.slice(ptr, ptr + len));
}
export function eval_fv(code) {
  if (!wasm_instance) throw new Error('init() 먼저 호출하세요');
  const [ptr, len] = write_string(code);
  const result_ptr = wasm_instance.exports.eval_fv_raw(ptr, len);
  const mem32 = new Uint32Array(wasm_memory.buffer);
  const result_len = mem32[result_ptr / 4];
  const result_str = read_string(result_ptr + 4, result_len);
  wasm_instance.exports.dealloc(ptr, len + 1);
  return JSON.parse(result_str);
}
export function fv_version() {
  if (!wasm_instance) return 'FV-Lang (미초기화)';
  const ptr = wasm_instance.exports.fv_version_raw();
  const mem = new Uint8Array(wasm_memory.buffer);
  let len = 0;
  while (mem[ptr + len] !== 0) len++;
  return read_string(ptr, len);
}
"
