### `src/integrity_checker.fl` - SHA 해시 체인 무결성

```fl
// ============================================================
// integrity_checker.fl - 해시 체인 무결성 증명
// 각 레코드의 prev_hash가 이전 레코드의 hash와 일치하는지 검증
// ============================================================

extern fn printf(fmt: string) -> i32;

// -------------------------------------------------------
// IntegrityReport: 검증 결과 보고서
// -------------------------------------------------------
struct IntegrityReport {
    total_checked: i64,
    chain_ok: i64,        // 체인이 끊기지 않은 레코드 수
    chain_broken: i64,    // 체인이 끊긴 레코드 수 (위변조 의심)
    first_broken_seq: i64, // 최초 체인 파괴 지점
    hash_collision: i64,  // 해시 충돌 수
    tombstone_count: i64, // 삭제 마커 수
    pass: i64,            // 1 = 전체 통과
}

// -------------------------------------------------------
// check_chain: 로그 전체의 해시 체인 검증
// 로직: records[i].prev_hash == records[i-1].hash 이어야 함
// -------------------------------------------------------
fn check_chain(store: *LogStore, report: *IntegrityReport) -> i64 {
    report.total_checked = store.count;
    report.chain_ok = 0;
    report.chain_broken = 0;
    report.first_broken_seq = -1;
    report.hash_collision = 0;
    report.tombstone_count = 0;
    report.pass = 1;

    if (store.count == 0) {
        println("[INTEGRITY] Empty store - trivially valid");
        report.pass = 1;
        return 1;
    }

    // 첫 레코드: prev_hash == "GENESIS" 이어야 함
    if (store.records[0].prev_hash == "GENESIS") {
        report.chain_ok = report.chain_ok + 1;
    } else {
        report.chain_broken = report.chain_broken + 1;
        report.first_broken_seq = store.records[0].seq;
        report.pass = 0;
        println("[INTEGRITY] GENESIS chain broken at seq=1");
    }

    // 이후 레코드: 이전 레코드 hash와 연결 확인
    var i: i64 = 1;
    while (i < store.count) {
        var prev_hash: string = store.records[i - 1].hash;
        var cur_prev_hash: string = store.records[i].prev_hash;

        if (prev_hash == cur_prev_hash) {
            report.chain_ok = report.chain_ok + 1;
        } else {
            report.chain_broken = report.chain_broken + 1;
            if (report.first_broken_seq == -1) {
                report.first_broken_seq = store.records[i].seq;
            }
            report.pass = 0;
            println("[INTEGRITY] Chain BROKEN at seq="
                + to_string(store.records[i].seq));
        }

        // Tombstone 카운트
        if (store.records[i].is_tombstone == 1) {
            report.tombstone_count = report.tombstone_count + 1;
        }

        i = i + 1;
    }
    return report.pass;
}

// -------------------------------------------------------
// check_seq_monotonic: 시퀀스 번호 단조 증가 검증
// -------------------------------------------------------
fn check_seq_monotonic(store: *LogStore) -> i64 {
    var i: i64 = 1;
    while (i < store.count) {
        if (store.records[i].seq <= store.records[i - 1].seq) {
            println("[INTEGRITY] SEQ NOT MONOTONIC at idx=" + to_string(i)
                + " seq=" + to_string(store.records[i].seq));
            return 0;
        }
        i = i + 1;
    }
    println("[INTEGRITY] Sequence monotonic: OK");
    return 1;
}

// -------------------------------------------------------
// print_report: 보고서 출력
// -------------------------------------------------------
fn print_integrity_report(report: *IntegrityReport) -> i64 {
    println("=== Integrity Report ===");
    println("  Total checked : " + to_string(report.total_checked));
    println("  Chain OK      : " + to_string(report.chain_ok));
    println("  Chain broken  : " + to_string(report.chain_broken));
    println("  Tombstones    : " + to_string(report.tombstone_count));
    if (report.first_broken_seq >= 0) {
        println("  First broken  : seq=" + to_string(report.first_broken_seq));
    }
    if (report.pass == 1) {
        println("  RESULT        : PASS");
    } else {
        println("  RESULT        : FAIL");
    }
    return report.pass;
}
```

