// ============================================================
// zero_validation_test.fl - 제로-밸리데이션 테스트 러너
// ============================================================

extern fn printf(fmt: string) -> i32;

fn test_zero_validation() -> i64 {
    println("=== Zero-Validation Test ===");

    var store: LogStore;
    log_init(&store);

    // 1. 대량 삽입 (검증 없이)
    var n: i64 = 1000;   // MAX_RECORDS 제한으로 1000개 (확장 시 10000)
    var inserted: i64 = bulk_insert(&store, n, 253);

    // 2. 삽입 수 검증
    var count_ok: i64 = bulk_verify_count(&store, n);

    // 3. 해시 체인 무결성 검증
    var report: IntegrityReport;
    var chain_ok: i64 = check_chain(&store, &report);
    var seq_ok: i64 = check_seq_monotonic(&store);
    print_integrity_report(&report);

    // 4. 랜덤 샘플 GET 검증 (10개 샘플)
    println("=== Sample GET Verification ===");
    var sample_pass: i64 = 0;
    var i: i64 = 0;
    while (i < 10) {
        var idx: i64 = i * 97;   // 결정론적 샘플링
        if (idx >= n) {
            idx = n - 1;
        }
        var key: string = generate_key(idx);
        var expected_val: string = generate_value(idx);
        var result: QueryResult = engine_get(&store, key);

        if (result.found == 1 && result.value == expected_val) {
            sample_pass = sample_pass + 1;
        } else {
            println("  FAIL: key=" + key + " expected=" + expected_val
                + " got=" + result.value);
        }
        i = i + 1;
    }
    println("Sample GET: " + to_string(sample_pass) + "/10 passed");

    // 5. 최종 판정
    if (count_ok == 1 && chain_ok == 1 && seq_ok == 1 && sample_pass == 10) {
        println("ZERO-VALIDATION TEST: PASS");
        return 0;
    }
    println("ZERO-VALIDATION TEST: FAIL");
    return 1;
}

fn main() -> i64 {
    return test_zero_validation();
}
