### `src/failover.fl` - 장애 감지 & 복구

```fl
// ============================================================
// failover.fl - 장애 감지 & 자동 복구
// ============================================================

extern fn printf(fmt: string) -> i32;

// -------------------------------------------------------
// simulate_primary_failure: 253 서버 장애 시뮬레이션
// -------------------------------------------------------
fn simulate_primary_failure(state: *ReplicationState) -> i64 {
    println("[FAILOVER] Primary 253 FAILED");
    state.primary.status = SRV_DEAD;
    return 0;
}

// -------------------------------------------------------
// promote_replica: Replica 73을 새 Primary로 승격
// 데이터 유실 없이 Replica의 로그를 Primary 역할로 전환
// -------------------------------------------------------
fn promote_replica(state: *ReplicationState) -> i64 {
    if (state.replica.status == SRV_DEAD) {
        println("[FAILOVER] Cannot promote - Replica 73 also DOWN");
        return -1;
    }

    println("[FAILOVER] Promoting Replica 73 to Primary");
    println("[FAILOVER] Data preserved: "
        + to_string(state.replica.log.count) + " records");

    // 73이 새 Primary 역할 수행 (server_id 변경 없이 역할 전환)
    // 실제 구현에서는 새 쓰기를 73으로 리다이렉트
    state.primary.status = SRV_DEAD;
    state.replica.server_id = 253;   // 새 Primary ID 부여

    println("[FAILOVER] Failover complete - New Primary: 73 (promoted)");
    return 0;
}

// -------------------------------------------------------
// recover_server: 장애 서버 복구 후 데이터 재동기화
// -------------------------------------------------------
fn recover_server(state: *ReplicationState) -> i64 {
    println("[FAILOVER] Recovering old Primary 253...");

    // 복구된 서버는 Replica로 재시작
    state.primary.status = SRV_ALIVE;
    state.primary.server_id = 73;    // 구 primary가 이제 replica

    // 현재 Primary(73 승격)에서 누락 레코드 복제
    var old_count: i64 = state.primary.log.count;
    var new_count: i64 = state.replica.log.count;
    var gap: i64 = new_count - old_count;

    println("[FAILOVER] Recovery gap: " + to_string(gap) + " records to catchup");

    // gap 레코드를 Primary 로그에서 복제
    var i: i64 = old_count;
    while (i < state.replica.log.count) {
        var key: string = state.replica.log.records[i].key;
        var value: string = state.replica.log.records[i].value;
        var op: i64 = state.replica.log.records[i].op;
        log_append(&state.primary.log, op, key, value, state.replica.server_id);
        i = i + 1;
    }

    println("[FAILOVER] Recovery complete - records synced: " + to_string(gap));
    return gap;
}

// -------------------------------------------------------
// verify_no_data_loss: 장애 복구 후 데이터 유실 없음 검증
// -------------------------------------------------------
fn verify_no_data_loss(state: *ReplicationState, test_key: string) -> i64 {
    // Replica(새 Primary)에서 데이터 확인
    var result: QueryResult = engine_get(&state.replica.log, test_key);
    if (result.found == 1) {
        println("[FAILOVER] Data integrity OK: key=" + test_key
            + " value=" + result.value);
        return 1;
    }
    println("[FAILOVER] Data LOST: key=" + test_key + " not found in Replica");
    return 0;
}
