## Phase 4: 타임 트래블 쿼리

### `src/time_travel.fl` - 시점 기반 쿼리 엔진

설계 핵심: Mandate-DB의 불변 로그가 곧 타임 트래블의 기반입니다. `timestamp <= target_time`인 레코드만 고려하면 과거 시점의 완벽한 상태를 재현할 수 있습니다.

```fl
// ============================================================
// time_travel.fl - 타임 트래블 쿼리 엔진
// "시점 T의 key K 값은?" → 타임스탬프 <= T인 로그만 재생
// ============================================================

extern fn printf(fmt: string) -> i32;

// -------------------------------------------------------
// tt_get_at: 특정 시점 T에서의 key 값 조회
// 로직: timestamp <= target_ts 인 레코드 중 가장 최신 반환
// -------------------------------------------------------
fn tt_get_at(store: *LogStore, key: string, target_ts: i64) -> QueryResult {
    var result: QueryResult;
    result.found = 0;
    result.key = key;
    result.value = "";
    result.timestamp = 0;
    result.seq = -1;

    // 역순 탐색: 타임스탬프 조건 충족하는 최신 레코드 찾기
    var i: i64 = store.count - 1;
    while (i >= 0) {
        if (store.records[i].timestamp <= target_ts) {
            if (store.records[i].key == key) {
                if (store.records[i].is_tombstone == 1) {
                    // 이 시점에 삭제된 상태
                    result.found = 0;
                    return result;
                }
                result.found = 1;
                result.value = store.records[i].value;
                result.timestamp = store.records[i].timestamp;
                result.seq = store.records[i].seq;
                return result;
            }
        }
        i = i - 1;
    }
    return result;
}

// -------------------------------------------------------
// tt_scan_at: 특정 시점 T에서의 prefix 범위 스캔
// -------------------------------------------------------
fn tt_scan_at(store: *LogStore, prefix: string, target_ts: i64) -> i64 {
    var count: i64 = 0;
    println("[TIMETRAVEL] SCAN at ts=" + to_string(target_ts)
        + " prefix=" + prefix);

    var i: i64 = 0;
    while (i < store.count) {
        // 타임스탬프 필터
        if (store.records[i].timestamp > target_ts) {
            i = i + 1;
            continue;
        }

        var rec_key: string = store.records[i].key;
        var plen: i64 = length(prefix);
        var klen: i64 = length(rec_key);

        // 접두사 매칭
        var match: i64 = 1;
        if (klen < plen) {
            match = 0;
        }
        if (match == 1) {
            var j: i64 = 0;
            while (j < plen) {
                if (char_at(rec_key, j) != char_at(prefix, j)) {
                    match = 0;
                    j = plen;
                }
                j = j + 1;
            }
        }

        if (match == 1) {
            // 이 시점 기준 최신 상태 확인
            var result: QueryResult = tt_get_at(store, rec_key, target_ts);
            if (result.found == 1) {
                println("  [ts=" + to_string(target_ts) + "] "
                    + rec_key + " = " + result.value);
                count = count + 1;
            }
        }
        i = i + 1;
    }
    println("[TIMETRAVEL] Found " + to_string(count) + " records at ts=" + to_string(target_ts));
    return count;
}

// -------------------------------------------------------
// tt_diff: 두 시점 사이에 변경된 키 목록 추출
// -------------------------------------------------------
fn tt_diff(store: *LogStore, ts_from: i64, ts_to: i64) -> i64 {
    println("[TIMETRAVEL] DIFF: ts_from=" + to_string(ts_from)
        + " ts_to=" + to_string(ts_to));
    var changed: i64 = 0;

    var i: i64 = 0;
    while (i < store.count) {
        var rec_ts: i64 = store.records[i].timestamp;
        if (rec_ts > ts_from && rec_ts <= ts_to) {
            println("  CHANGED: seq=" + to_string(store.records[i].seq)
                + " key=" + store.records[i].key
                + " op=" + to_string(store.records[i].op));
            changed = changed + 1;
        }
        i = i + 1;
    }
    println("[TIMETRAVEL] Total changes: " + to_string(changed));
    return changed;
}
```

